      history: [],
      // File transfer
      filesPanelOpen: false,
      transfers: [],            // {id, name, size, received|sent, direction, from, to, done}
      // Whiteboard
      wbActive: false,
      wbColor: '#60a5fa',
      // Live annotation over the shared screen (own transparent layer,
